catalog_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below
    function recalculateTotalAttendees() {
    var onsiteTotal = 0;
    var virtualTotal = 0;

    var attendeesStr = g_form.getValue('number_of_attendees');
    if (!attendeesStr) return;

    var rows = JSON.parse(attendeesStr);

    rows.forEach(function(row) {
      var onsite = parseInt(row.onsite || 0);
      var virtual = parseInt(row.virtual || 0);

      onsiteTotal += isNaN(onsite) ? 0 : onsite;
      virtualTotal += isNaN(virtual) ? 0 : virtual;
    });

    g_form.setValue('total_number_of_onside_attendees', onsiteTotal);
    g_form.setValue('total_number_of_virtual_attendees', virtualTotal);
  }

  recalculateTotalAttendees();
}
